const upsertCashAccount = `-- name: UpsertCashAccount :one
INSERT INTO cash.accounts (company_id, account_id, kind, bank_name, account_number, active)
VALUES ($1, $2, $3, $4, $5, $6)
ON CONFLICT (company_id, account_id) DO UPDATE
SET kind = EXCLUDED.kind, bank_name = EXCLUDED.bank_name,
    account_number = EXCLUDED.account_number, active = EXCLUDED.active
RETURNING company_id, account_id, kind, bank_name, account_number, active, created_at
`

type UpsertCashAccountParams struct {
	CompanyID     uuid.UUID
	AccountID     uuid.UUID
	Kind          string
	BankName      string
	AccountNumber string
	Active        bool
}

func (q *Queries) UpsertCashAccount(ctx context.Context, arg UpsertCashAccountParams) (CashAccount, error) {
	row := q.db.QueryRow(ctx, upsertCashAccount,
		arg.CompanyID,
		arg.AccountID,
		arg.Kind,
		arg.BankName,
		arg.AccountNumber,
		arg.Active,
	)
	var i CashAccount
	err := row.Scan(
		&i.CompanyID,
		&i.AccountID,
		&i.Kind,
		&i.BankName,
		&i.AccountNumber,
		&i.Active,
		&i.CreatedAt,
	)
	return i, err
}

